package com.mavric.health.hospital.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.hospital.domain.Requests.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerHospitalStoreTest.Fixture;
import static com.mavric.health.persistence.sqlserver.SqlServerHospitalStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Service/store integration with synthetic servlet/executor/transaction doubles, no HTTP or SQL server. */
class HospitalServiceSqlServerTest {
 final Fixture f=new Fixture();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final HospitalService service=new HospitalService(f.store,sql,access);
 void actor(String role){f.actor(role);when(access.actor()).thenReturn(f.actor);TraceContext.REQUEST.set(f.request);}
 @BeforeEach void setup(){actor("AUD");}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void twoSelectedReadsHaveExactShapesRolesAndNoBranchSqlOrWrite(){f.resources.add(resource());f.admissions.add(admission());assertEquals(7,((List<Map<String,Object>>)service.resources()).getFirst().size());assertEquals(11,((List<Map<String,Object>>)service.admissions()).getFirst().size());verify(access).roles("ADM","PRO","ASI","AUD");verify(access).roles("PRO","ASI","AUD");verify(access,times(2)).module("HOSPITAL");verify(access,never()).branch(anyString());verify(access,never()).write(anyString(),any(String[].class));verifyNoInteractions(sql);assertEquals(List.of(SqlServerProcedure.HOSPITAL_RESOURCES,SqlServerProcedure.HOSPITAL_ADMISSIONS),f.calls);}
 @Test void resourcesRoleMatrixAndAdmissionsExcludesAdmWithoutSp(){for(String role:List.of("ADM","PRO","ASI","AUD","REC","PAC","SAD","SOP")){actor(role);int count=f.calls.size();if(Set.of("ADM","PRO","ASI","AUD").contains(role))service.resources();else{assertEquals(403,assertThrows(ApiException.class,service::resources).status);assertEquals(count,f.calls.size());}count=f.calls.size();if(Set.of("PRO","ASI","AUD").contains(role))service.admissions();else{assertEquals(403,assertThrows(ApiException.class,service::admissions).status);assertEquals(count,f.calls.size());}}verifyNoInteractions(sql);}
 @Test void missingRequestAnonymousMalformedHostAndDiscordantActorDenyBeforeSp(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,service::resources).status);verifyNoInteractions(access);actor("AUD");when(access.actor()).thenThrow(new ApiException(401,"UNAUTHENTICATED","Safe"));assertEquals(401,assertThrows(ApiException.class,service::admissions).status);reset(access);actor("AUD");f.request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,service::resources).status);actor("AUD");f.request.setAttribute("health.actor",new Actor(ACTOR,"Different","synthetic@example.test",TENANT,List.of("AUD"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,service::resources).status);actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("HOSPITAL")));assertEquals(403,assertThrows(ApiException.class,service::admissions).status);actor("SAD");var platform=new Actor(ACTOR,"Synthetic","synthetic@example.test",null,List.of("SAD"),"a".repeat(64));when(access.actor()).thenReturn(platform);f.request.setAttribute("health.actor",platform);f.request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,service::resources).status);verifyNoInteractions(f.executor,sql);}
 @Test void moduleGateRejectsAndSuspendedReadIsNotWriteGated(){doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("HOSPITAL");assertEquals(403,assertThrows(ApiException.class,service::admissions).status);verifyNoInteractions(f.executor,sql);reset(access);actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("HOSPITAL")));service.resources();service.admissions();verify(access,never()).write(anyString(),any(String[].class));verifyNoInteractions(sql);}
 @Test void forgedHeadersCannotChangeAuthorityAndCallerAttributesStayIntact(){var actor=f.actor;var host=f.request.getAttribute("health.tenant");f.request.addHeader("X-Tenant-Id",OTHER);f.request.addHeader("X-Roles","SAD");f.request.addHeader("Authorization","private-canary");service.resources();assertSame(actor,f.request.getAttribute("health.actor"));assertSame(host,f.request.getAttribute("health.tenant"));assertSame(f.request,TraceContext.REQUEST.get());assertNull(SecurityContextHolder.getContext().getAuthentication());assertEquals(TENANT,f.contexts.getFirst().tenantId());}
 @Test void mappingCommitAndSqlErrorNeverFallBackOrReturnFakeSuccess(){f.admissions.add(new LinkedHashMap<>());assertEquals(500,assertThrows(ApiException.class,service::admissions).status);assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,service::resources).status);doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,51002))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,service::resources);assertEquals(404,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("private-canary"));verifyNoInteractions(sql);}
 @Test void minimalSpringSelectsLegacyWithoutDatasourceSchedulerOrStore(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenantId()).thenReturn(TENANT);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(HospitalService.class);context.refresh();var legacy=context.getBean(HospitalService.class);assertEquals(List.of(),legacy.resources());assertEquals(List.of(),legacy.admissions());assertEquals(0,context.getBeanNamesForType(SqlServerHospitalStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verify(sql,times(2)).rows(anyString(),eq(TENANT));verifyNoInteractions(f.executor);}
 @Test void allThreeLegacyWritesRemainAvailableInOriginalConstructor(){when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);when(sql.json(any())).thenReturn("{}");when(sql.one(anyString(),any(Object[].class))).thenReturn(Map.of("id",ID,"branchId",OTHER));for(var selected:List.of(new HospitalService(sql,access))){selected.resource(new Resource(OTHER,"Synthetic","BED"));selected.admit(new Admission(OTHER,ID,"Synthetic"));selected.discharge(ID,2);}verify(sql,times(1)).call(eq("sp_resource_create"),any(Object[].class));verify(sql,times(1)).call(eq("sp_admit"),any(Object[].class));verify(sql,times(1)).call(eq("sp_discharge"),eq(TENANT),eq(ID),eq(ACTOR),eq(2));verify(access,times(3)).branch(OTHER);verifyNoInteractions(f.executor);}

 @Test void mixedConstructorWritesSelectExactlyThreeSpWithoutSqlOrBranch(){actor("ADM");assertEquals(6,((Map<?,?>)service.resource(resourceInput())).size());actor("PRO");var admission=(Map<?,?>)service.admit(admissionInput());assertEquals(11,admission.size());assertEquals(11,((Map<?,?>)service.discharge((String)admission.get("id"),1)).size());verify(access).write("HOSPITAL","ADM");verify(access,times(2)).write("HOSPITAL","PRO","ASI");verify(access,never()).branch(anyString());verifyNoInteractions(sql);assertEquals(List.of(SqlServerProcedure.HOSPITAL_RESOURCE_CREATE,SqlServerProcedure.HOSPITAL_ADMIT,SqlServerProcedure.HOSPITAL_DISCHARGE),f.calls);}
 @Test void writeRoleAndHostMatrixDeniesBeforeInputsAndEffects(){for(String role:List.of("ADM","PRO","ASI","AUD","PAC","SAD","SOP")){actor(role);if(!role.equals("ADM"))assertEquals(403,assertThrows(ApiException.class,()->service.resource(null)).status);if(!Set.of("PRO","ASI").contains(role)){assertEquals(403,assertThrows(ApiException.class,()->service.admit(null)).status);assertEquals(403,assertThrows(ApiException.class,()->service.discharge(null,0)).status);}}actor("PRO");f.request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.admit(null)).status);actor("PRO");f.request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,()->service.discharge(null,0)).status);TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.admit(null)).status);verifyNoInteractions(f.executor,sql);}
 @Test void accessWritePrecedesDtoAndStoreStatusModuleGuardsRemainEffective(){actor("PRO");doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("HOSPITAL","PRO","ASI");assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.admit(null)).code);assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.discharge(null,0)).code);reset(access);actor("ASI");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("HOSPITAL")));assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.admit(admissionInput())).code);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->service.discharge(ID,1)).code);verifyNoInteractions(f.executor,sql);}
 @Test void admitAsiAndWritesKeepCallerActorHostAndThreadLocalIntact(){actor("ASI");var actor=f.actor;var host=f.request.getAttribute("health.tenant");service.admit(admissionInput());service.discharge(ID,1);assertSame(actor,f.request.getAttribute("health.actor"));assertSame(host,f.request.getAttribute("health.tenant"));assertSame(f.request,TraceContext.REQUEST.get());assertNull(SecurityContextHolder.getContext().getAuthentication());verifyNoInteractions(sql);}
 @Test void writeInputAndReturnedMappingErrorsRollbackAndNoFallback(){actor("ADM");assertEquals(400,assertThrows(ApiException.class,()->service.resource(null)).status);f.mutate=row->row.put("active",false);assertEquals(500,assertThrows(ApiException.class,()->service.resource(resourceInput())).status);assertEquals("rollback",f.manager.events.getLast());actor("PRO");assertEquals(400,assertThrows(ApiException.class,()->service.admit(null)).status);assertEquals(400,assertThrows(ApiException.class,()->service.discharge(ID,0)).status);f.mutate=row->{};f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.admit(admissionInput())).status);assertEquals(409,assertThrows(ApiException.class,()->service.discharge(ID,Integer.MAX_VALUE)).status);verifyNoInteractions(sql);}
 @Test void secondDischargeConflictIsModeledNotInventedIdempotence(){actor("PRO");service.discharge(ID,1);doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,51003))).when(f.executor).execute(eq(SqlServerProcedure.HOSPITAL_DISCHARGE),any(),eq(ID),eq(2));var e=assertThrows(ApiException.class,()->service.discharge(ID,2));assertEquals(409,e.status);assertNull(e.getCause());verify(f.executor,times(1)).execute(eq(SqlServerProcedure.HOSPITAL_DISCHARGE),any(),eq(ID),eq(1));verify(f.executor,times(1)).execute(eq(SqlServerProcedure.HOSPITAL_DISCHARGE),any(),eq(ID),eq(2));verifyNoInteractions(sql);}
}
